import { Question, Subject, ProfileLevel, KnowledgeType, CognitiveSkill } from '../types';

type Spec = {
  topic: string;
  text: string;
  correct: string;
  partial?: string;
  wrong1: string;
  wrong2: string;
  isMathHeavy?: boolean;
};

const skills: CognitiveSkill[] = ['Spatial Reasoning','Formula Dependency','Graph Illiteracy','Reading Comprehension','Logical Deduction','Conceptual Application'];
const levels: ProfileLevel[] = ['Z','F','P','C'];

function build(subject: Subject, prefix: string, level: ProfileLevel, specs: Spec[]): Question[] {
  return specs.map((s, i) => {
    const knowledgeType = ['K1','K2','K3','K4'][i % 4] as KnowledgeType;
    const partial = s.partial ?? s.wrong1;
    return {
      id: `${prefix}_${level}_X_${String(i + 1).padStart(2,'0')}`,
      subject, profileLevel: level, knowledgeType, topic: s.topic,
      text: s.text,
      options: [
        { id: 'a', text: s.correct, points: 5 },
        { id: 'b', text: partial, points: 1 },
        { id: 'c', text: s.wrong1, points: 0 },
        { id: 'd', text: s.wrong2, points: 0 }
      ],
      cognitiveSkills: [skills[i % skills.length], skills[(i + 2) % skills.length]],
      difficulty: level === 'Z' ? (i % 2 ? 2 : 1) : level === 'F' ? (i % 3 ? 2 : 1) : level === 'P' ? (i % 3) + 1 : (i % 2) + 2,
      isMathHeavy: s.isMathHeavy,
      textLength: s.text.length < 90 ? 'short' : s.text.length < 170 ? 'medium' : 'long'
    };
  });
}

